export class CurveDataTableStringColumn {
    header;
    fieldName;
    sortable;
    displayMethod;
    constructor(fieldName, header, displayMethod, sortable = false) {
        this.header = header;
        this.fieldName = fieldName;
        this.sortable = sortable;
        this.displayMethod = displayMethod
            ? displayMethod
            : (fieldValue) => `${fieldValue}`;
    }
}
